                                       function build(a                )        {if(!a.length||a[0]===null)return null;const root  ={v:a[0],l:null,r:null},q    =[root];let i=1;for(let j=0;j<q.length&&i<a.length;j++){for(const key of ['l','r']         ){const v=a[i++];if(v!==null&&v!==undefined){const n  ={v,l:null,r:null};q[j][key]=n;q.push(n);}}}return root;}const root=build(values);function from(n       ,sum       )       {if(!n)return 0;const next=sum+n.v;return Number(next===target)+from(n.l,next)+from(n.r,next);}function visit(n       )       {return n?from(n,0)+visit(n.l)+visit(n.r):0;}return visit(root);
}

